async function saveCoastlineDrafts(document){if(!guard('zones_weather_edit'))return;state.coastlineDrafts=document;localStorage.setItem(COASTLINE_DRAFT_KEY,JSON.stringify(document));const result=await saveAdminDocumentNow('coastline-overrides',document);if(!result.ok)alert(`Kystlinjekladden blev kun gemt lokalt: ${result.error}`);}
function renderAdminCoastlineEditor(){renderCoastlineEditor(content,{zones:state.zones,collection:state.zoneCollection,document:state.coastlineDrafts,onSave:saveCoastlineDrafts});}

function renderZones(){content.innerHTML=`<article class="admin-card"><h2>Zoner</h2><div class="toolbar"><input id="zoneSearch" placeholder="Søg zone"><select id="zoneType"><option value="">Alle kysttyper</option>${[...new Set(state.zones.map(z=>z.properties?.coastType).filter(Boolean))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></article><div id="zoneList" class="admin-table-wrap"></div>`;const draw=()=>{const q=document.querySelector('#zoneSearch').value.toLowerCase(),t=document.querySelector('#zoneType').value;const rows=state.zones.filter(z=>(!t||z.properties?.coastType===t)&&JSON.stringify(z.properties).toLowerCase().includes(q));document.querySelector('#zoneList').innerHTML=`<table class="admin-table"><thead><tr><th>Zone</th><th>Kysttype</th><th>Område</th><th>Vejrkilde</th></tr></thead><tbody>${rows.slice(0,250).map(z=>{const p=z.properties||{},w=state.conditions.zones?.[p.id]||{};return `<tr><td>${esc(p.name||p.id)}</td><td>${esc(p.coastType||'–')}</td><td>${esc(p.region||p.area||'–')}</td><td>${esc(w.provider||'ingen data')}</td></tr>`}).join('')}</tbody></table>`};document.querySelector('#zoneSearch').oninput=draw;document.querySelector('#zoneType').onchange=draw;draw();}



function directionReviews(){try{return JSON.parse(localStorage.getItem(DIRECTION_REVIEW_KEY)||'{}')}catch{return{}}}
function saveDirectionReviews(rows){localStorage.setItem(DIRECTION_REVIEW_KEY,JSON.stringify(rows));queueAdminDocumentSave('direction-reviews',{schemaVersion:1,zones:rows,updatedAt:new Date().toISOString()});}
function normalizeDeg(v){return ((Number(v)%360)+360)%360;}
function angleDiff(a,b){const d=Math.abs(normalizeDeg(a)-normalizeDeg(b));return Math.min(d,360-d);}
function bearingDeg(from,to){const [lon1,lat1]=from.map(x=>Number(x)*Math.PI/180),[lon2,lat2]=to.map(x=>Number(x)*Math.PI/180);const y=Math.sin(lon2-lon1)*Math.cos(lat2);const x=Math.cos(lat1)*Math.sin(lat2)-Math.sin(lat1)*Math.cos(lat2)*Math.cos(lon2-lon1);return normalizeDeg(Math.atan2(y,x)*180/Math.PI);}
function destinationPoint(origin,bearing,distanceKm=4){const R=6371,[lon1,lat1]=origin.map(x=>Number(x)*Math.PI/180),br=normalizeDeg(bearing)*Math.PI/180,d=distanceKm/R;const lat2=Math.asin(Math.sin(lat1)*Math.cos(d)+Math.cos(lat1)*Math.sin(d)*Math.cos(br));const lon2=lon1+Math.atan2(Math.sin(br)*Math.sin(d)*Math.cos(lat1),Math.cos(d)-Math.sin(lat1)*Math.sin(lat2));return [lon2*180/Math.PI,lat2*180/Math.PI];}
function directionLabel(deg){const labels=['N','NØ','Ø','SØ','S','SV','V','NV'];return `${labels[Math.round(normalizeDeg(deg)/45)%8]} ${Math.round(normalizeDeg(deg))}°`;}
function pointDistanceKm(a,b){if(!a||!b)return null;const R=6371,[lon1,lat1]=a.map(x=>Number(x)*Math.PI/180),[lon2,lat2]=b.map(x=>Number(x)*Math.PI/180);const dLat=lat2-lat1,dLon=lon2-lon1,h=Math.sin(dLat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(h));}
function directionAuditPriority(feature,reviews){const p=feature.properties||{},r=reviews[p.id];if(r?.status==='verified')return 99;if(!p.dataPoint||!p.pinPoint)return 0;const distance=pointDistanceKm(p.dataPoint,p.pinPoint),pointBearing=bearingDeg(p.dataPoint,p.pinPoint),diff=angleDiff(p.onshoreDirectionDeg,pointBearing);if(distance<.15||distance>8||diff>45)return 1;if((p.onshoreDirectionReviewStatus||'').includes('manual')||(p.placementReview&&p.placementReview!=='verified')||p.directionAnchorAuditRecommended===true)return 2;return 3;}

let directionMap=null,directionLayers=[];
function clearDirectionLayers(){if(directionMap)directionLayers.forEach(x=>directionMap.removeLayer(x));directionLayers=[];}
function addDirectionLayer(layer){layer.addTo(directionMap);directionLayers.push(layer);return layer;}
function baseAnchors(properties,review){
 const stored=Array.isArray(review?.anchors)&&review.anchors.length?review.anchors:Array.isArray(properties.directionAnchors)&&properties.directionAnchors.length?properties.directionAnchors:[{id:'primary',name:'Primær kystdel',dataPoint:properties.dataPoint,pinPoint:properties.pinPoint,onshoreDirectionDeg:properties.onshoreDirectionDeg,weight:1}];
 return stored.map((a,i)=>({id:String(a.id||`anchor-${i+1}`),name:String(a.name||`Kystdel ${i+1}`),dataPoint:Array.isArray(a.dataPoint)?a.dataPoint.map(Number):null,pinPoint:Array.isArray(a.pinPoint)?a.pinPoint.map(Number):null,onshoreDirectionDeg:normalizeDeg(a.onshoreDirectionDeg??(a.dataPoint&&a.pinPoint?bearingDeg(a.dataPoint,a.pinPoint):0)),weight:Number.isFinite(Number(a.weight))?Math.max(.1,Number(a.weight)):1,verified:Boolean(a.verified)}));
}
function arrowEnd(anchor){return anchor.dataPoint?destinationPoint(anchor.dataPoint,anchor.onshoreDirectionDeg,4):null;}
function drawDirectionZone(feature,anchors,selectedAnchorId,onPointMoved){
 if(!window.L)return;const p=feature.properties||{};clearDirectionLayers();
 const coords=[];const collect=x=>{if(Array.isArray(x)&&typeof x[0]==='number'&&typeof x[1]==='number')coords.push([x[1],x[0]]);else if(Array.isArray(x))x.forEach(collect)};collect(feature.geometry?.coordinates||[]);
 if(coords.length)addDirectionLayer(L.polygon(coords,{color:'#d8a232',weight:4,fillOpacity:.06,interactive:false}));
 if(Array.isArray(p.coastLine)&&p.coastLine.length)addDirectionLayer(L.polyline(p.coastLine.map(x=>[x[1],x[0]]),{color:'#5ee093',weight:5,interactive:false}));
 anchors.forEach((anchor,index)=>{
  const selected=anchor.id===selectedAnchorId;const suffix=anchors.length>1?` · ${anchor.name}`:'';
  if(anchor.dataPoint){const marker=addDirectionLayer(L.marker([anchor.dataPoint[1],anchor.dataPoint[0]],{draggable:true,title:`Marint datapunkt${suffix}`,icon:L.divIcon({className:'direction-point-icon',html:`<span class="direction-point sea ${selected?'selected':''}">${index+1}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).bindTooltip(`Blåt punkt: marint datapunkt${suffix}`));marker.on('dragend',e=>{const ll=e.target.getLatLng();onPointMoved(anchor.id,'dataPoint',[ll.lng,ll.lat]);});}
  if(anchor.pinPoint){const marker=addDirectionLayer(L.marker([anchor.pinPoint[1],anchor.pinPoint[0]],{draggable:true,title:`Strand-/landpunkt${suffix}`,icon:L.divIcon({className:'direction-point-icon',html:`<span class="direction-point land ${selected?'selected':''}">${index+1}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).bindTooltip(`Grønt punkt: strand-/landpunkt${suffix}`));marker.on('dragend',e=>{const ll=e.target.getLatLng();onPointMoved(anchor.id,'pinPoint',[ll.lng,ll.lat]);});}
  const end=arrowEnd(anchor);if(anchor.dataPoint&&end){addDirectionLayer(L.polyline([[anchor.dataPoint[1],anchor.dataPoint[0]],[end[1],end[0]]],{color:selected?'#ff4f4f':'#ff8d8d',weight:selected?7:4,opacity:selected?1:.7,interactive:false}));addDirectionLayer(L.circleMarker([end[1],end[0]],{radius:selected?6:4,color:'#ff4f4f',fillColor:'#ff4f4f',fillOpacity:1,interactive:false}).bindTooltip(`Retningen peger hertil: ${directionLabel(anchor.onshoreDirectionDeg)}${suffix}`));}
 });
 const bounds=directionLayers.flatMap(x=>x.getBounds?[x.getBounds()]:[]).reduce((a,b)=>a?a.extend(b):b,null);if(bounds?.isValid()&&!directionMap.__hasFit){directionMap.fitBounds(bounds.pad(.3));directionMap.__hasFit=true;}
}

function renderDirectionAudit(){
 const reviews=directionReviews();const active=state.zones.filter(z=>z.properties?.zoneStatus==='active');const verified=active.filter(z=>reviews[z.properties?.id]?.status==='verified').length;
 content.innerHTML=`<article class="admin-card direction-intro"><div class="rule-card-head"><div><h2>Geografisk kontrol af kystdele</h2><p>Flyt punkterne direkte på kortet. <b>Blå skal ligge i havet</b>, <b>grøn ved stranden/land</b>, og den røde retning skal pege fra havet ind mod land.</p></div><span class="badge">${verified}/${active.length} zoner godkendt</span></div><ol class="direction-steps"><li>Vælg en zone og derefter den kystdel, du vil redigere.</li><li>Træk det blå og grønne punkt til de rigtige steder.</li><li>Klik <b>Beregn retning fra punkterne</b>, eller finjustér graderne.</li><li>Ved en bugtet kyst kan du tilføje flere kystdele. Hver kystdel får sit eget havpunkt, landpunkt og retning.</li><li>Godkend zonen og download til sidst en ny <code>zones.geojson</code>.</li></ol><p class="hint">Den røde cirkel er slutningen af retningen – altså den ende, retningen peger imod. Ændringer gemmes lokalt i browseren, indtil du eksporterer zonefilen.</p></article>
 <div class="direction-layout"><article class="admin-card direction-queue"><div class="toolbar"><input id="directionSearch" placeholder="Søg efter zone"><select id="directionFilter"><option value="pending">Ikke godkendte først</option><option value="uncertain">Kun mistænkelige</option><option value="verified">Kun godkendte</option><option value="all">Alle zoner</option></select></div><div id="directionZoneList" class="direction-zone-list"></div></article>
 <article class="admin-card direction-work"><div id="directionEmpty" class="empty">Vælg en zone i listen.</div><div id="directionEditor" hidden><div class="rule-card-head"><div><span id="directionStatus" class="badge"></span><h2 id="directionName"></h2><p id="directionMeta" class="muted"></p></div><button id="directionOpenMain" class="admin-button secondary">Vis på hovedkortet</button></div>
 <div id="directionMap" class="direction-map"></div><div class="direction-legend"><span><i class="dot sea"></i> Flytbart havpunkt</span><span><i class="dot land"></i> Flytbart landpunkt</span><span><i class="line coast"></i> Kystlinje</span><span><i class="line arrow"></i> Retningen peger mod den røde cirkel</span></div>
 <section class="anchor-manager"><div class="rule-card-head"><div><h3>Kystdele i zonen</h3><p class="hint">En lige kyst behøver normalt én. Brug flere ved bugter, odder eller kyster der vender forskelligt.</p></div><button id="anchorAdd" type="button" class="admin-button secondary">+ Tilføj kystdel</button></div><div id="anchorTabs" class="anchor-tabs"></div></section>
 <div class="form-grid anchor-editor"><label>Navn på kystdelen<input id="anchorName" placeholder="Fx vestlige kyst"></label><label>Vægt<input id="anchorWeight" type="number" min="0.1" max="5" step="0.1"><span class="hint">Normalt 1. Højere tal bruges kun, hvis denne kystdel fysisk repræsenterer en større del af zonen.</span></label><label>Havpunkt – længdegrad<input id="anchorSeaLon" type="number" step="0.000001"></label><label>Havpunkt – breddegrad<input id="anchorSeaLat" type="number" step="0.000001"></label><label>Landpunkt – længdegrad<input id="anchorLandLon" type="number" step="0.000001"></label><label>Landpunkt – breddegrad<input id="anchorLandLat" type="number" step="0.000001"></label></div>
 <div class="direction-controls"><label>Pålandsretning <strong id="directionValue"></strong><input id="directionRange" type="range" min="0" max="359" step="1"></label><label>Præcis grad<input id="directionNumber" type="number" min="0" max="359" step="1"></label></div><div class="toolbar direction-nudge"><button id="directionMinus5" class="admin-button secondary" type="button">−5°</button><button id="directionPlus5" class="admin-button secondary" type="button">+5°</button><button id="directionUsePointBearing" class="admin-button secondary" type="button">Beregn retning fra punkterne</button><button id="anchorDelete" class="admin-button danger" type="button">Slet denne kystdel</button></div><div id="directionChecks" class="direction-checks"></div>
 <fieldset class="direction-confirmations"><legend>Bekræft zonen</legend><label><input id="directionConfirmSea" type="checkbox"> Alle blå punkter ligger i havet</label><label><input id="directionConfirmLand" type="checkbox"> Alle grønne punkter ligger ved deres kyst/land</label><label><input id="directionConfirmArrow" type="checkbox"> Alle røde retninger peger fra hav mod land</label></fieldset><label>Bemærkning<textarea id="directionNote" placeholder="Fx: To kystdele fordi bugten vender både mod vest og syd."></textarea></label><div class="direction-actions"><button id="directionFlag" class="admin-button secondary">Kræver senere kontrol</button><button id="directionApprove" class="admin-button" disabled>Godkend og gå til næste</button></div></div></article></div>
 <article class="admin-card"><h2>Eksport</h2><p>Download den komplette zonefil. Primær kystdel gemmes også i de gamle felter for bagudkompatibilitet; alle kystdele gemmes i <code>directionAnchors</code>.</p><div class="toolbar"><button id="directionExport" class="admin-button">Download zones.geojson</button><button id="directionExportReview" class="admin-button secondary">Download kontrolrapport</button><button id="directionReset" class="admin-button danger">Nulstil lokale godkendelser</button></div></article>`;
 let selectedId=null,selectedAnchorId=null,currentAnchors=[];const list=document.querySelector('#directionZoneList');
 const visibleZones=()=>{const q=document.querySelector('#directionSearch').value.trim().toLowerCase(),f=document.querySelector('#directionFilter').value;return active.filter(z=>{const p=z.properties||{},r=reviews[p.id],priority=directionAuditPriority(z,reviews);if(q&&!`${p.id} ${p.name} ${p.region}`.toLowerCase().includes(q))return false;if(f==='verified')return r?.status==='verified';if(f==='uncertain')return priority<=2&&r?.status!=='verified';if(f==='pending')return r?.status!=='verified';return true;}).sort((a,b)=>directionAuditPriority(a,reviews)-directionAuditPriority(b,reviews)||(a.properties?.name||'').localeCompare(b.properties?.name||'','da'));};
 const drawList=()=>{const rows=visibleZones();list.innerHTML=rows.length?rows.map(z=>{const p=z.properties||{},r=reviews[p.id];return `<button class="direction-zone-row ${selectedId===p.id?'selected':''}" data-zone-id="${esc(p.id)}"><span><b>${esc(p.name||p.id)}</b><small>${esc(p.id)} · ${esc(p.region||'')}</small></span><span class="badge ${r?.status==='verified'?'active':r?.status==='flagged'?'draft':''}">${r?.status==='verified'?'Godkendt':r?.status==='flagged'?'Senere kontrol':'Ikke kontrolleret'}</span></button>`}).join(''):'<div class="empty">Ingen zoner matcher.</div>';list.querySelectorAll('[data-zone-id]').forEach(b=>b.onclick=()=>selectZone(b.dataset.zoneId));};
 const persistDraft=()=>{if(!selectedId)return;reviews[selectedId]={...(reviews[selectedId]||{}),anchors:structuredClone(currentAnchors),note:document.querySelector('#directionNote')?.value.trim()||'',updatedAt:new Date().toISOString()};saveDirectionReviews(reviews);};
 const selectedAnchor=()=>currentAnchors.find(a=>a.id===selectedAnchorId)||currentAnchors[0];
 const updateChecks=()=>{const a=selectedAnchor();if(!a)return;const bearing=a.dataPoint&&a.pinPoint?bearingDeg(a.dataPoint,a.pinPoint):null;document.querySelector('#directionChecks').innerHTML=`<div class="metric-card"><span>Hav → land fra punkter</span><strong>${bearing==null?'Mangler':directionLabel(bearing)}</strong></div><div class="metric-card"><span>Valgt retning</span><strong>${directionLabel(a.onshoreDirectionDeg)}</strong></div><div class="metric-card"><span>Forskel</span><strong>${bearing==null?'–':Math.round(angleDiff(a.onshoreDirectionDeg,bearing))+'°'}</strong></div><div class="metric-card"><span>Afstand</span><strong>${a.dataPoint&&a.pinPoint?pointDistanceKm(a.dataPoint,a.pinPoint).toFixed(2)+' km':'–'}</strong></div>`;};
 const redrawMap=()=>{const feature=active.find(z=>z.properties?.id===selectedId);if(feature&&directionMap)drawDirectionZone(feature,currentAnchors,selectedAnchorId,(anchorId,key,coords)=>{const a=currentAnchors.find(x=>x.id===anchorId);a[key]=coords;if(key==='dataPoint'||key==='pinPoint'){if(a.dataPoint&&a.pinPoint)a.onshoreDirectionDeg=Math.round(bearingDeg(a.dataPoint,a.pinPoint));}persistDraft();renderAnchorEditor();redrawMap();});};
 const renderAnchorTabs=()=>{const wrap=document.querySelector('#anchorTabs');wrap.innerHTML=currentAnchors.map((a,i)=>`<button type="button" data-anchor-id="${esc(a.id)}" class="anchor-tab ${a.id===selectedAnchorId?'active':''}"><b>${i+1}. ${esc(a.name)}</b><small>${directionLabel(a.onshoreDirectionDeg)}</small></button>`).join('');wrap.querySelectorAll('[data-anchor-id]').forEach(b=>b.onclick=()=>{selectedAnchorId=b.dataset.anchorId;renderAnchorEditor();redrawMap();});};
 const renderAnchorEditor=()=>{const a=selectedAnchor();if(!a)return;renderAnchorTabs();document.querySelector('#anchorName').value=a.name;document.querySelector('#anchorWeight').value=a.weight;document.querySelector('#anchorSeaLon').value=a.dataPoint?.[0]??'';document.querySelector('#anchorSeaLat').value=a.dataPoint?.[1]??'';document.querySelector('#anchorLandLon').value=a.pinPoint?.[0]??'';document.querySelector('#anchorLandLat').value=a.pinPoint?.[1]??'';document.querySelector('#directionRange').value=a.onshoreDirectionDeg;document.querySelector('#directionNumber').value=Math.round(a.onshoreDirectionDeg);document.querySelector('#directionValue').textContent=directionLabel(a.onshoreDirectionDeg);document.querySelector('#anchorDelete').disabled=currentAnchors.length<=1;updateChecks();};
 const selectZone=id=>{selectedId=id;drawList();const feature=active.find(z=>z.properties?.id===id),p=feature.properties||{},r=reviews[id]||{};currentAnchors=baseAnchors(p,r);selectedAnchorId=currentAnchors[0]?.id;document.querySelector('#directionEmpty').hidden=true;document.querySelector('#directionEditor').hidden=false;document.querySelector('#directionName').textContent=p.name||id;document.querySelector('#directionMeta').textContent=`${id} · ${p.region||'Ukendt område'} · ${p.coastType||'ukendt kysttype'}`;document.querySelector('#directionStatus').textContent=r.status==='verified'?'Godkendt':r.status==='flagged'?'Kræver senere kontrol':'Ikke kontrolleret';document.querySelector('#directionNote').value=r.note||'';const c=r.confirmations||{};document.querySelector('#directionConfirmSea').checked=Boolean(c.seaPointInWater);document.querySelector('#directionConfirmLand').checked=Boolean(c.landPointAtCoast);document.querySelector('#directionConfirmArrow').checked=Boolean(c.arrowSeaToLand);setTimeout(()=>{if(!directionMap){directionMap=L.map('directionMap',{zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(directionMap);}directionMap.__hasFit=false;directionMap.invalidateSize();renderAnchorEditor();redrawMap();},0);document.querySelector('#directionOpenMain').onclick=()=>window.open(`./?zone=${encodeURIComponent(id)}`,'_blank');updateApprove();};
 const modifyAnchor=(fn)=>{const a=selectedAnchor();if(!a)return;fn(a);persistDraft();renderAnchorEditor();redrawMap();};
 ['anchorName','anchorWeight','anchorSeaLon','anchorSeaLat','anchorLandLon','anchorLandLat'].forEach(id=>document.querySelector('#'+id).onchange=()=>modifyAnchor(a=>{a.name=document.querySelector('#anchorName').value.trim()||a.name;a.weight=Math.max(.1,Number(document.querySelector('#anchorWeight').value)||1);a.dataPoint=[Number(document.querySelector('#anchorSeaLon').value),Number(document.querySelector('#anchorSeaLat').value)];a.pinPoint=[Number(document.querySelector('#anchorLandLon').value),Number(document.querySelector('#anchorLandLat').value)];}));
 const changeDirection=v=>modifyAnchor(a=>a.onshoreDirectionDeg=normalizeDeg(v));document.querySelector('#directionRange').oninput=e=>changeDirection(e.target.value);document.querySelector('#directionNumber').onchange=e=>changeDirection(e.target.value);document.querySelector('#directionMinus5').onclick=()=>changeDirection(selectedAnchor().onshoreDirectionDeg-5);document.querySelector('#directionPlus5').onclick=()=>changeDirection(selectedAnchor().onshoreDirectionDeg+5);document.querySelector('#directionUsePointBearing').onclick=()=>modifyAnchor(a=>{if(a.dataPoint&&a.pinPoint)a.onshoreDirectionDeg=Math.round(bearingDeg(a.dataPoint,a.pinPoint));});
 document.querySelector('#anchorAdd').onclick=()=>{const source=selectedAnchor()||currentAnchors[0];const id=`anchor-${Date.now().toString(36)}`;currentAnchors.push({id,name:`Kystdel ${currentAnchors.length+1}`,dataPoint:source?.dataPoint?[source.dataPoint[0]+.01,source.dataPoint[1]]:null,pinPoint:source?.pinPoint?[source.pinPoint[0]+.01,source.pinPoint[1]]:null,onshoreDirectionDeg:source?.onshoreDirectionDeg??0,weight:1,verified:false});selectedAnchorId=id;persistDraft();renderAnchorEditor();redrawMap();};
 document.querySelector('#anchorDelete').onclick=()=>{if(currentAnchors.length<=1)return;if(!confirm('Slet denne kystdel?'))return;currentAnchors=currentAnchors.filter(a=>a.id!==selectedAnchorId);selectedAnchorId=currentAnchors[0].id;persistDraft();renderAnchorEditor();redrawMap();};
 const confirmationState=()=>({seaPointInWater:document.querySelector('#directionConfirmSea').checked,landPointAtCoast:document.querySelector('#directionConfirmLand').checked,arrowSeaToLand:document.querySelector('#directionConfirmArrow').checked});function updateApprove(){const c=confirmationState();document.querySelector('#directionApprove').disabled=!(c.seaPointInWater&&c.landPointAtCoast&&c.arrowSeaToLand&&currentAnchors.length);};['directionConfirmSea','directionConfirmLand','directionConfirmArrow'].forEach(id=>document.querySelector('#'+id).onchange=updateApprove);
 document.querySelector('#directionApprove').onclick=()=>{const c=confirmationState();if(!(c.seaPointInWater&&c.landPointAtCoast&&c.arrowSeaToLand))return;reviews[selectedId]={status:'verified',anchors:structuredClone(currentAnchors.map(a=>({...a,verified:true}))),note:document.querySelector('#directionNote').value.trim(),verifiedAt:new Date().toISOString(),confirmations:c};saveDirectionReviews(reviews);drawList();const next=visibleZones().find(z=>z.properties?.id!==selectedId);if(next)selectZone(next.properties.id);};document.querySelector('#directionFlag').onclick=()=>{reviews[selectedId]={status:'flagged',anchors:structuredClone(currentAnchors),note:document.querySelector('#directionNote').value.trim(),updatedAt:new Date().toISOString(),confirmations:confirmationState()};saveDirectionReviews(reviews);drawList();};
 document.querySelector('#directionSearch').oninput=drawList;document.querySelector('#directionFilter').onchange=drawList;document.querySelector('#directionExport').onclick=()=>{const output=structuredClone(state.zoneRegistry.collection||{type:'FeatureCollection',features:state.zoneRegistry.all||state.zones});for(const f of output.features||[]){const p=f.properties||{},r=reviews[p.id];if(r?.anchors?.length){p.directionAnchors=r.anchors.map(a=>({...a,onshoreDirectionDeg:Math.round(normalizeDeg(a.onshoreDirectionDeg))}));const primary=p.directionAnchors[0];p.dataPoint=primary.dataPoint;p.pinPoint=primary.pinPoint;p.onshoreDirectionDeg=primary.onshoreDirectionDeg;p.onshoreDirectionSource='manual multi-anchor geographic review in RavRadar admin';p.onshoreDirectionAuditedAt=r.verifiedAt||r.updatedAt;p.onshoreDirectionReviewStatus=r.status==='verified'?'manually-verified':'manual-review-needed';if(r.note)p.onshoreDirectionReviewNote=r.note;}}download('zones.geojson',output);};document.querySelector('#directionExportReview').onclick=()=>download(`ravradar-geografisk-kontrol-${new Date().toISOString().slice(0,10)}.json`,{schemaVersion:'2.0',exportedAt:new Date().toISOString(),reviews});document.querySelector('#directionReset').onclick=()=>{if(confirm('Nulstil alle lokale geografiske kontroller?')){localStorage.removeItem(DIRECTION_REVIEW_KEY);renderDirectionAudit();}};
 drawList();const first=visibleZones()[0];if(first)selectZone(first.properties.id);
}

function renderObservations(){const obs=JSON.parse(localStorage.getItem('ravradar-observations-v2')||'[]');const finds=obs.filter(x=>x.found||x.result==='found').length;content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Observationer</h2><div class="metric">${obs.length}</div></article><article class="admin-card"><h2>Registrerede fund</h2><div class="metric">${finds}</div></article><article class="admin-card"><h2>Vejrsnapshots</h2><div class="metric">${obs.filter(x=>x.weatherSnapshot).length}</div><p class="muted">Bevares ved central oprydning</p></article></div><article class="admin-card"><h2>Eksport og databeskyttelse</h2><p>Eksporten fjerner bruger-id og præcis GPS-position. Vejrsnapshot og regelforklaring bevares til analyse.</p><button id="exportObs" class="admin-button">Eksportér pseudonymiseret JSON</button></article>`;document.querySelector('#exportObs').onclick=()=>{const rows=obs.map(({anonymous_id,user_id,gps,...r})=>({...r,gps:gps?{accuracy:gps.accuracy??null}:null}));download('ravradar-observationer.json',{exportedAt:new Date().toISOString(),privacyProfile:'pseudonymised',rows})};}

async function renderUsers(){
 content.innerHTML=`<article class="admin-card"><h2>Eksperter og rettigheder</h2><p class="muted">Få, brede tilladelser. Du kan til enhver tid ændre dem igen.</p><div id="profilesList" class="admin-grid"><p class="muted">Henter brugere…</p></div></article>`;
 const host=document.querySelector('#profilesList');
 try{state.profiles=await listProfiles();if(!state.profiles.length){host.innerHTML='<div class="empty">Ingen profiler blev fundet. Kør SQL-opdateringen til 4.0.63 i Supabase én gang.</div>';return;}
 host.innerHTML=state.profiles.map(profile=>{const active=new Set((profile.user_permissions||[]).filter(x=>x.enabled).map(x=>x.permission_key));return `<article class="admin-card permission-card" data-user-id="${esc(profile.id)}"><div class="rule-card-head"><div><h3>${esc(profile.display_name||profile.email)}</h3><p class="muted">${esc(profile.email||'')} · ${esc(profile.role||'expert')}</p></div><span class="badge ${profile.is_active!==false?'active':'draft'}">${profile.is_active!==false?'Aktiv':'Deaktiveret'}</span></div><div class="permission-list">${PERMISSIONS.map(p=>`<label class="permission-option"><input type="checkbox" name="${esc(p.id)}" ${active.has(p.id)||profile.role==='owner'?'checked':''} ${profile.role==='owner'?'disabled':''}><span>${esc(p.label)}</span></label>`).join('')}</div>${profile.role==='owner'?'<p class="hint">Owner har altid alle rettigheder.</p>':'<button class="admin-button save-user-permissions" type="button">Gem rettigheder</button><p class="form-status"></p>'}</article>`}).join('');
 host.querySelectorAll('.save-user-permissions').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-user-id]');const status=card.querySelector('.form-status');const values={};PERMISSIONS.forEach(p=>values[p.id]=card.querySelector(`[name="${p.id}"]`).checked);button.disabled=true;status.textContent='Gemmer…';try{await savePermissions(card.dataset.userId,values);status.textContent='Rettighederne er gemt og gælder med det samme.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
 }catch(error){host.innerHTML=`<div class="empty">${esc(error.message)}</div>`;}
}

