function renderDocumentation(){content.innerHTML=`<article class="admin-card"><span class="eyebrow">Beskyttet projektviden</span><h2>Dokumentationscenter</h2><p>Håndbogen og interne styringsdokumenter åbnes kun inde i administrationen efter Supabase-kontrol.</p><button class="admin-button" id="openProtectedHandbook">Åbn håndbogen</button></article>`;document.querySelector('#openProtectedHandbook').onclick=()=>{state.tab='handbook';document.querySelectorAll('.admin-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab==='handbook'));render();};}

function renderSystem(){content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Version</h2><div class="metric">${VERSION}</div></article><article class="admin-card"><h2>Lokale administratorregler</h2><div class="metric">${adminRules().length}</div></article><article class="admin-card"><h2>Regelhistorik</h2><div class="metric">${history().length}</div></article></div><article class="admin-card"><h2>Vedligeholdelse</h2><div class="toolbar"><button id="exportDiag" class="admin-button secondary">Eksportér diagnostik</button><button id="clearCaches" class="admin-button danger">Ryd RavRadar-caches</button><button id="logoutAdmin" class="admin-button secondary">Lås administration</button></div><p class="hint">Cacheknappen rydder kun caches, hvis navn starter med “ravradar”. Den sletter ikke observationer, ture eller regler.</p></article><article class="admin-card"><h2>Seneste regelændringer</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Tid</th><th>Handling</th><th>Regel</th></tr></thead><tbody>${history().slice(0,20).map(x=>`<tr><td>${new Date(x.at).toLocaleString('da-DK')}</td><td>${esc(x.action)}</td><td>${esc(x.rule?.name)}</td></tr>`).join('')||'<tr><td colspan="3">Ingen ændringer</td></tr>'}</tbody></table></div></article>`;document.querySelector('#exportDiag').onclick=()=>{const waterLevelZones=Object.fromEntries(Object.entries(state.conditions.zones||{}).map(([zoneId,z])=>[zoneId,{zoneName:z.waterLevel?.diagnostic?.zoneName||state.zones.find(f=>f.properties?.id===zoneId)?.properties?.name||zoneId,provider:z.provider,currentWaterLevelCm:z.current?.waterLevelCm??null,waterLevel:z.waterLevel??null,modelSteps:z.modelSteps??null,dmiCache:z.dmiCache??null,attempts:z.attempts??[],acquisition:z.acquisition??null}]));download('ravradar-diagnostik.json',{version:VERSION,exportedAt:new Date().toISOString(),conditionsGeneratedAt:state.conditions.generatedAt??null,health:state.health,weatherEngine:state.conditions.weatherEngine??null,dataQuality:state.conditions.dataQuality??null,weatherZoneCount:Object.keys(state.conditions.zones||{}).length,zoneCount:state.zoneRegistry.counts.registered,activeZoneCount:state.zoneRegistry.counts.active,legacyZoneCount:state.zoneRegistry.counts.legacy,adminRuleCount:adminRules().length,waterLevelDiagnostics:{description:'Aktuel vandstand er baseret på DMI oceanObs: direkte lokal station eller kystbaseret interpolation mellem én station på hver side. Prognosemodeller vises separat.',zones:waterLevelZones}})};document.querySelector('#clearCaches').onclick=async()=>{if(!confirm('Ryd RavRadars app-caches?'))return;for(const name of await caches.keys())if(name.toLowerCase().startsWith('ravradar'))await caches.delete(name);alert('RavRadar-caches er ryddet.');};document.querySelector('#logoutAdmin').onclick=()=>{sessionStorage.removeItem(SESSION_KEY);location.replace('./')};}


function renderHistory(){
 const zones=state.zones.map(z=>z.properties).sort((a,b)=>(a.name||'').localeCompare(b.name||'','da'));
 content.innerHTML=`<article class="admin-card"><h2>Historisk analyse</h2><p class="muted">Filtrér registrerede ravture og sammenlign fund med det vejrsnapshot og den RavScore, der blev gemt på turdagen.</p><div class="toolbar"><input id="historyDate" type="date"><select id="historyZone"><option value="">Alle zoner</option>${zones.map(z=>`<option value="${esc(z.id)}">${esc(z.name)}</option>`).join('')}</select><select id="historyResult"><option value="">Alle resultater</option><option value="none">Intet fund</option><option value="small">Små stykker</option><option value="medium">Noget rav</option><option value="good">Godt fund</option></select><button id="clearHistory" class="admin-button secondary">Ryd filtre</button></div></article><div id="historyOutput"></div>`;
 const draw=()=>{const summary=historicalSummary({date:document.querySelector('#historyDate').value||null,zoneId:document.querySelector('#historyZone').value||null,result:document.querySelector('#historyResult').value||null});document.querySelector('#historyOutput').innerHTML=`<div class="admin-grid"><article class="admin-card"><h3>Ture</h3><div class="metric">${summary.count}</div></article><article class="admin-card"><h3>Fund</h3><div class="metric">${summary.finds}</div></article><article class="admin-card"><h3>Fundrate</h3><div class="metric">${summary.successRate==null?'–':Math.round(summary.successRate*100)+'%'}</div></article><article class="admin-card"><h3>Gns. RavScore</h3><div class="metric">${summary.averages.ravScore??'–'}</div></article></div><article class="admin-card admin-table-wrap"><table class="admin-table"><thead><tr><th>Dato</th><th>Zone</th><th>Resultat</th><th>RavScore</th><th>Vandstand</th><th>Vind</th><th>Bølger</th><th>Kilde</th></tr></thead><tbody>${summary.rows.map(r=>`<tr><td>${esc(String(r.observed_at).slice(0,10))}</td><td>${esc(r.zone_name||r.zone_id)}</td><td>${esc(r.result)}</td><td>${esc(r.rav_score??'–')}</td><td>${esc(r.water_level_cm??'–')} cm</td><td>${esc(r.wind_speed_mps??'–')} m/s</td><td>${esc(r.wave_height_m??'–')} m</td><td>${esc(r.weather_snapshot?.provider||r.weather_snapshot?.current?.provider||'–')}</td></tr>`).join('')||'<tr><td colspan="8">Ingen observationer matcher filtrene.</td></tr>'}</tbody></table></article>`};
 ['historyDate','historyZone','historyResult'].forEach(id=>document.querySelector('#'+id).onchange=draw);document.querySelector('#clearHistory').onclick=()=>{document.querySelector('#historyDate').value='';document.querySelector('#historyZone').value='';document.querySelector('#historyResult').value='';draw()};draw();
}
function renderLearning(){
 const analysis=analyzeObservations(),model=loadAdaptiveModel(),decisions=decisionHistory();
 const versions=listAdaptiveModelVersions();
 content.innerHTML=`<div class="admin-grid"><article class="admin-card"><h2>Aktiv model</h2><div class="metric">v${model.version}</div><p class="muted">${esc(model.source)}${model.updatedAt?' · '+new Date(model.updatedAt).toLocaleString('da-DK'):''}</p></article><article class="admin-card"><h2>Datagrundlag</h2><div class="metric">${analysis.sampleSize||0}</div><p class="muted">${analysis.status==='ready'?'Klar til forslag':'Der kræves mindst 12 ture og fire af hvert udfald.'}</p></article><article class="admin-card"><h2>Beslutninger</h2><div class="metric">${decisions.length}</div><p class="muted">Godkendelser og afvisninger på denne enhed</p></article></div><article class="admin-card"><div class="rule-card-head"><div><h2>Machine Learning Studio</h2><p class="muted">Godkendte forslag opretter en ny aktiv modelversion. Alle versioner gemmes, så du kan rulle tilbage uden at kode.</p></div><button id="rollbackModel" class="admin-button danger">Nulstil model</button></div></article><div id="suggestionList" class="admin-grid">${analysis.suggestions?.length?analysis.suggestions.map(suggestionCard).join(''):`<div class="empty">${analysis.status==='ready'?'Ingen nye statistisk underbyggede forslag.':'Der er endnu ikke tilstrækkeligt balanceret feedback til sikre forslag.'}</div>`}</div><article class="admin-card"><h2>Modelversioner</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Version</th><th>Kilde</th><th>Tid</th><th></th></tr></thead><tbody>${versions.map(v=>`<tr><td>v${v.version}${v.version===model.version?' · aktiv':''}</td><td>${esc(v.source)}</td><td>${v.updatedAt?new Date(v.updatedAt).toLocaleString('da-DK'):'Fabriksmodel'}</td><td>${v.version===model.version?'':`<button class="admin-button secondary" data-restore-model="${v.version}">Aktivér som ny version</button>`}</td></tr>`).join('')}</tbody></table></div></article><article class="admin-card"><h2>Beslutningshistorik</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Tid</th><th>Beslutning</th><th>Forslag</th><th>Model</th></tr></thead><tbody>${decisions.slice(0,50).map(d=>`<tr><td>${new Date(d.at).toLocaleString('da-DK')}</td><td>${d.decision==='approved'?'Godkendt':'Afvist'}</td><td>${esc(d.suggestion?.title||d.suggestionId)}</td><td>${esc(d.modelVersion??'–')}</td></tr>`).join('')||'<tr><td colspan="4">Ingen beslutninger endnu.</td></tr>'}</tbody></table></div></article>`;
 content.querySelectorAll('[data-approve-ml]').forEach(b=>b.onclick=()=>{const s=analysis.suggestions.find(x=>x.id===b.dataset.approveMl);if(!s)return;if(!confirm(`Godkend “${s.title}”? Ændringen bruges i fremtidige prognoser.`))return;const updated=applyApprovedSuggestion(s);recordDecision(s,'approved',updated.version);renderLearning();});
 content.querySelectorAll('[data-reject-ml]').forEach(b=>b.onclick=()=>{const s=analysis.suggestions.find(x=>x.id===b.dataset.rejectMl);if(!s)return;recordDecision(s,'rejected',model.version);renderLearning();});
 document.querySelector('#rollbackModel').onclick=()=>{if(confirm('Nulstil alle godkendte modeltilpasninger?')){rollbackAdaptiveModel();renderLearning();}};content.querySelectorAll('[data-restore-model]').forEach(button=>button.onclick=()=>{if(confirm(`Aktivér model v${button.dataset.restoreModel} som en ny version?`)){activateAdaptiveModelVersion(Number(button.dataset.restoreModel));renderLearning();}});
}
function suggestionCard(s){return `<article class="admin-card ml-suggestion"><div class="rule-card-head"><div><span class="badge">${esc(s.confidence)}% sikkerhed</span><h3>${esc(s.title)}</h3></div></div><p>${esc(s.description)}</p><p><b>Foreslået effekt:</b> ${esc(s.expectedEffect)}</p><p class="hint">Datagrundlag: ${esc(s.evidence.successful)} fund og ${esc(s.evidence.unsuccessful)} ture uden fund. Ingen kildekode omskrives.</p><div class="rule-card-actions"><button class="admin-button" data-approve-ml="${esc(s.id)}">Godkend og aktivér</button><button class="admin-button danger" data-reject-ml="${esc(s.id)}">Afvis</button></div></article>`}

const PRIORITY_LEVELS={low:800,normal:500,high:250,critical:50};
function priorityLevel(value=500){const n=Number(value);return n<=100?'critical':n<=300?'high':n>=700?'low':'normal'}
function priorityExplanation(level){return ({low:'Behandles efter almindelige regler.',normal:'Standard for almindelige regler.',high:'Behandles før normale regler ved overlap.',critical:'Kun til grænser eller regler, der skal have forrang.'})[level]}
function help(label,text,impact,example){return `<button type="button" class="field-help" aria-label="Hjælp til ${esc(label)}" data-help-title="${esc(label)}" data-help="${esc(text)}" data-impact="${esc(impact)}" data-example="${esc(example)}">?</button>`}
function openRuleEditor(rule=null,advice=false){
 state.editingId=rule?.id||null;const r=rule||{id:uid(),name:'',status:'draft',kind:advice?'annotation':'bonus',knowledgeClass:'expert',confidence:'mellem',priority:500,geography:{scope:'national'},source:{type:'expert',title:''},conditions:{},effect:{scoreAdjustment:0,explanation:''},version:1};
 ruleDialog.dataset.dirty='false';document.querySelector('#ruleDialogTitle').textContent=rule?'Redigér regel':advice?'Nyt godt råd':'Ny regel';
 const selectedZones=new Set(r.geography?.zoneIds||[]), level=priorityLevel(r.priority);
 document.querySelector('#ruleFormBody').innerHTML=`
 <div class="rule-builder">
  <section class="rule-step"><div class="step-number">1</div><div><h3>Hvad har du observeret?</h3><p class="hint">Skriv reglen med dine egne ord. Det gør den lettere at genkende senere.</p><label class="full">Titel ${help('Titel','Et kort navn på observationen.','Ændrer ikke scoren, men gør reglen nem at finde.','Frisk pålandsvind efter stille periode')}<input name="name" required value="${esc(r.name)}" placeholder="Fx Frisk pålandsvind efter stille periode"></label></div></section>
  <section class="rule-step"><div class="step-number">2</div><div><h3>Hvornår gælder reglen?</h3><div class="form-grid"><label>Status ${help('Status','Kladde bruges ikke i beregningen. Aktiv bruges i RavScore.','Aktivering kan ændre prognoser med det samme.','Gem først som kladde og test den.')}<select name="status"><option value="draft" ${r.status==='draft'?'selected':''}>Kladde – påvirker ikke RavScore</option><option value="active" ${r.status==='active'?'selected':''}>Aktiv – bruges i beregningen</option><option value="inactive" ${r.status==='inactive'?'selected':''}>Inaktiv – gemt men slukket</option></select></label><label>Geografisk omfang ${help('Geografisk omfang','Vælg hele Danmark, et større område eller konkrete zoner.','Bestemmer hvilke kyster reglen kan ramme.','Nordjyske østkyst kan udvides og enkelte zoner fravælges.')}<select name="scope" id="geoScope"><option value="national" ${r.geography?.scope==='national'?'selected':''}>Hele Danmark</option><option value="area" ${r.geography?.scope==='area'?'selected':''}>Større geografisk område</option><option value="zone" ${r.geography?.scope==='zone'?'selected':''}>Enkeltzoner</option><option value="coastType" ${r.geography?.scope==='coastType'?'selected':''}>Kysttype (avanceret)</option></select></label></div>
  <div id="geoAreaBox"><label>Vælg område<select id="geoArea"><option value="">Vælg…</option>${Object.keys(GEOGRAPHIC_AREAS).map(a=>`<option ${r.geography?.area===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label><p id="geoAreaSummary" class="hint"></p></div>
  <div id="zonePicker"><label>Søg zoner<input id="zonePickerSearch" placeholder="Søg navn eller område"></label><div id="zonePickerList" class="zone-picker-list"></div><p id="zonePickerSummary" class="hint"></p></div>
  <label id="coastTypeBox">Kysttyper<input name="coastTypes" value="${esc((r.geography?.coastTypes||[]).join(', '))}" placeholder="Fx Vesterhavet"></label>
  <div><h4>Betingelser</h4><p class="hint">Alle valgte betingelser skal være opfyldt samtidig.</p><div id="conditionList" class="condition-list"></div><button type="button" id="addCondition" class="admin-button secondary">+ Tilføj betingelse</button></div></div></section>
  <section class="rule-step"><div class="step-number">3</div><div><h3>Hvad skal reglen gøre?</h3><div class="form-grid"><label>Handling ${help('Handling','Vælg om reglen giver point, trækker point, sætter en score eller kun viser et råd.','Dette er reglens direkte virkning på RavScore.','Giv 8 point ekstra når betingelserne er opfyldt.')}<select name="kind"><option value="bonus" ${r.kind==='bonus'?'selected':''}>Giv flere point</option><option value="penalty" ${r.kind==='penalty'?'selected':''}>Træk point fra</option><option value="persistence" ${r.kind==='persistence'?'selected':''}>Virker i timer/dage efter hændelse</option><option value="gate" ${r.kind==='gate'?'selected':''}>Sæt maksimum / blokér</option><option value="override" ${r.kind==='override'?'selected':''}>Sæt fast score</option><option value="annotation" ${r.kind==='annotation'?'selected':''}>Vis kun et råd</option></select></label><label>Scoreændring ${help('Scoreændring','Antal point reglen lægger til eller trækker fra.','Ændrer RavScore direkte.','8 giver +8 point; -8 giver -8 point.')}<input name="scoreAdjustment" type="number" min="-100" max="100" value="${esc(r.effect?.scoreAdjustment??0)}"></label><label>Fast score<input name="overrideScore" type="number" min="0" max="100" value="${esc(r.effect?.score??'')}"></label><label class="switch-line"><input name="block" type="checkbox" ${r.effect?.block?'checked':''}> Blokér vurderingen</label></div><label class="full">Forklaring / godt råd<textarea name="explanation" required placeholder="Forklar hvorfor reglen betyder noget for ravjagt.">${esc(r.effect?.explanation||'')}</textarea></label><button type="button" id="explainRule" class="admin-button secondary">Forklar denne regel</button><div id="ruleNaturalExplanation" class="rule-preview"></div></div></section>
  <section class="rule-step"><div class="step-number">4</div><div><h3>Se virkningen før du gemmer</h3><div id="ruleLivePreview" class="live-score-preview"></div><div id="ruleWarnings" class="rule-warnings"></div></div></section>
  <details class="advanced-settings"><summary>Avancerede indstillinger</summary><div class="form-grid"><label>Dokumentation ${help('Dokumentation','Hvor kommer erfaringen fra?','Bruges til sporbarhed og vurdering, ikke direkte score.','Ravjæger-erfaring eller dokumenteret viden.')}<select name="knowledgeClass"><option value="expert" ${r.knowledgeClass==='expert'?'selected':''}>Erfaring fra ravjæger</option><option value="documented" ${r.knowledgeClass==='documented'?'selected':''}>Dokumenteret viden</option><option value="data-derived" ${r.knowledgeClass==='data-derived'?'selected':''}>Udledt af RavRadar-data</option><option value="hypothesis" ${r.knowledgeClass==='hypothesis'?'selected':''}>Hypotese til afprøvning</option></select></label><label>Tillid<select name="confidence"><option value="lav" ${r.confidence==='lav'?'selected':''}>Usikker</option><option value="mellem" ${r.confidence==='mellem'?'selected':''}>Rimelig sikker</option><option value="stor" ${r.confidence==='stor'?'selected':''}>Meget sikker</option></select></label><label>Kilde / ravjæger<input name="sourceTitle" value="${esc(r.source?.title||'')}" placeholder="Fx navn, bog, artikel eller samtale"></label><label>Prioritet ${help('Prioritet','Afgør rækkefølgen når flere regler påvirker det samme.','Højere niveau behandles før normale regler.','Normal passer til de fleste regler.')}<select name="priorityLevel"><option value="low" ${level==='low'?'selected':''}>Lav</option><option value="normal" ${level==='normal'?'selected':''}>Normal</option><option value="high" ${level==='high'?'selected':''}>Høj</option><option value="critical" ${level==='critical'?'selected':''}>Kritisk</option></select><span id="priorityHelp" class="hint">${priorityExplanation(level)}</span></label><label class="full">Interne noter<textarea name="notes">${esc(r.notes||'')}</textarea></label></div></details>
 </div>`;
 const existing=conditionsToRows(r.conditions||{});existing.forEach(addConditionRow);document.querySelector('#addCondition').onclick=()=>{addConditionRow();markDirty();updatePreview()};
 const markDirty=()=>ruleDialog.dataset.dirty='true';
 const picker=document.querySelector('#zonePickerList');
 const drawZones=()=>{const q=(document.querySelector('#zonePickerSearch').value||'').toLowerCase();picker.innerHTML=state.zones.filter(z=>!q||`${z.properties?.name} ${z.properties?.region}`.toLowerCase().includes(q)).map(z=>`<label class="zone-choice"><input type="checkbox" value="${esc(z.properties.id)}" ${selectedZones.has(z.properties.id)?'checked':''}> <span>${esc(z.properties?.name||z.properties.id)}<small>${esc(z.properties?.region||'')}</small></span></label>`).join('');picker.querySelectorAll('input').forEach(i=>i.onchange=()=>{i.checked?selectedZones.add(i.value):selectedZones.delete(i.value);markDirty();updateGeoSummary();updatePreview()})};
 const updateGeoSummary=()=>{const scope=document.querySelector('#geoScope').value, area=document.querySelector('#geoArea').value;document.querySelector('#geoAreaBox').hidden=scope!=='area';document.querySelector('#zonePicker').hidden=!['area','zone'].includes(scope);document.querySelector('#coastTypeBox').hidden=scope!=='coastType';if(scope==='area'&&area){const ids=matchingZoneIds(state.zones,area);if(!selectedZones.size&&!r.geography?.zoneIds?.length)ids.forEach(id=>selectedZones.add(id));document.querySelector('#geoAreaSummary').textContent=`Området matcher ${ids.length} zoner. ${selectedZones.size} er valgt; du kan fravælge enkelte nedenfor.`}document.querySelector('#zonePickerSummary').textContent=`${selectedZones.size} zoner valgt.`;drawZones()};
 const natural=()=>{const fd=new FormData(document.querySelector('#ruleForm'));const cs=[];document.querySelectorAll('.condition-row').forEach(row=>{const d=conditionDefs[row.querySelector('.cond-key').value]?.[0],v=row.querySelector('.cond-value').value;if(v)cs.push(`${d.toLowerCase()} ${v}`)});const action=fd.get('kind')==='annotation'?'viser et råd':fd.get('kind')==='override'?`sætter RavScore til ${fd.get('overrideScore')||0}`:`ændrer RavScore med ${Number(fd.get('scoreAdjustment')||0)>=0?'+':''}${fd.get('scoreAdjustment')||0} point`;return `Når ${cs.length?cs.join(' og '):'de valgte forhold gælder'}, ${action} i ${fd.get('scope')==='national'?'hele Danmark':selectedZones.size+' valgte zoner'}.`};
 const updatePreview=()=>{const fd=new FormData(document.querySelector('#ruleForm')),base=54,kind=fd.get('kind'),adj=Number(fd.get('scoreAdjustment')||0),after=kind==='override'?Number(fd.get('overrideScore')||base):Math.max(0,Math.min(100,base+adj));document.querySelector('#ruleLivePreview').innerHTML=`<div><span>Uden reglen</span><b>${base}</b></div><div><span>Med reglen</span><b>${after}</b></div><div><span>Ændring</span><b>${after-base>=0?'+':''}${after-base}</b></div>`;const warnings=[];if(!document.querySelectorAll('.condition-row .cond-value').length)warnings.push('Reglen har ingen betingelser og kan derfor gælde hele tiden.');if(fd.get('scope')!=='national'&&!selectedZones.size&&fd.get('scope')!=='coastType')warnings.push('Ingen zoner er valgt.');if(Math.abs(adj)>25)warnings.push('Reglen giver en meget stor scoreændring.');if(fd.get('priorityLevel')==='critical')warnings.push('Kritisk prioritet bør kun bruges, når reglen skal have forrang.');document.querySelector('#ruleWarnings').innerHTML=warnings.length?`<ul>${warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:'<p class="status-good">Ingen åbenlyse problemer fundet.</p>';document.querySelector('#ruleNaturalExplanation').textContent=natural()};
 document.querySelector('#zonePickerSearch').oninput=drawZones;document.querySelector('#geoScope').onchange=()=>{markDirty();selectedZones.clear();updateGeoSummary();updatePreview()};document.querySelector('#geoArea').onchange=()=>{const area=document.querySelector('#geoArea').value;selectedZones.clear();matchingZoneIds(state.zones,area).forEach(id=>selectedZones.add(id));markDirty();updateGeoSummary();updatePreview()};document.querySelector('[name=priorityLevel]').onchange=e=>{document.querySelector('#priorityHelp').textContent=priorityExplanation(e.target.value);updatePreview()};document.querySelector('#explainRule').onclick=updatePreview;document.querySelectorAll('#ruleFormBody input,#ruleFormBody select,#ruleFormBody textarea').forEach(el=>el.addEventListener('input',()=>{markDirty();updatePreview()}));document.querySelectorAll('.field-help').forEach(b=>b.onclick=()=>alert(`${b.dataset.helpTitle}\n\nHvad betyder det?\n${b.dataset.help}\n\nHvad ændrer det?\n${b.dataset.impact}\n\nEksempel:\n${b.dataset.example}`));
 updateGeoSummary();updatePreview();ruleDialog.showModal();
}

const conditionDefs={minWindSpeedMps:['Vindstyrke mindst','m/s'],maxWindSpeedMps:['Vindstyrke højst','m/s'],windDirection:['Vindretning','retning'],minWaveHeightM:['Bølgehøjde mindst','m'],maxWaveHeightM:['Bølgehøjde højst','m'],minWaterLevelCm:['Vandstand mindst','cm'],maxWaterLevelCm:['Vandstand højst','cm'],maxHoursSinceHighEnergy:['Højst timer siden kraftigt vejr','timer'],minBaseScore:['Grundscore mindst','point'],maxBaseScore:['Grundscore højst','point'],huntMode:['Jagtform','valg']};
function addConditionRow(row={key:'minWindSpeedMps',value:'',extra:''}){const wrap=document.querySelector('#conditionList');const div=document.createElement('div');div.className='condition-row';div.innerHTML=`<select class="cond-key">${Object.entries(conditionDefs).map(([k,v])=>`<option value="${k}" ${row.key===k?'selected':''}>${v[0]}</option>`).join('')}</select><select class="cond-op"><option value="value">Værdi</option></select><input class="cond-value" value="${esc(row.value)}" placeholder="Tal, N/NE/E… eller waders/beach"><button type="button" class="admin-button danger">×</button>`;div.querySelector('button').onclick=()=>div.remove();wrap.appendChild(div)}
function conditionsToRows(c){const rows=[];for(const k of ['minWindSpeedMps','maxWindSpeedMps','minWaveHeightM','maxWaveHeightM','minWaterLevelCm','maxWaterLevelCm','maxHoursSinceHighEnergy','minBaseScore','maxBaseScore'])if(c[k]!=null)rows.push({key:k,value:c[k]});if(c.huntModes?.length)rows.push({key:'huntMode',value:c.huntModes.join(',')});if(c.windDirectionRangesDeg?.length)rows.push({key:'windDirection',value:directionRangeToLabel(c.windDirectionRangesDeg[0])});return rows}

document.querySelector('#ruleForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();if(!guard('rules_edit'))return;const fd=new FormData(e.currentTarget);const old=state.editingId?adminRules().find(x=>x.id===state.editingId):null;const conditions={};document.querySelectorAll('.condition-row').forEach(row=>{const k=row.querySelector('.cond-key').value,v=row.querySelector('.cond-value').value.trim();if(!v)return;if(k==='huntMode')conditions.huntModes=v.split(',').map(x=>x.trim()).filter(Boolean);else if(k==='windDirection')conditions.windDirectionRangesDeg=[directionLabelToRange(v)];else conditions[k]=Number(v)});const scope=fd.get('scope'),area=document.querySelector('#geoArea')?.value||'',zoneIds=[...document.querySelectorAll('#zonePickerList input:checked')].map(x=>x.value),kind=fd.get('kind'),requestedStatus=fd.get('status');if(requestedStatus==='active'&&!guard('rules_publish','Du mangler rettigheden Aktivér regler direkte. Gem reglen som kladde i stedet.'))return;const level=fd.get('priorityLevel')||'normal';const geography={scope,...(scope==='area'?{area,zoneIds}:scope==='zone'?{zoneIds}:scope==='coastType'?{coastTypes:String(fd.get('coastTypes')||'').split(',').map(x=>x.trim()).filter(Boolean)}:{})};const rule={id:old?.id||uid(),name:fd.get('name'),status:requestedStatus,kind,knowledgeClass:fd.get('knowledgeClass'),confidence:fd.get('confidence'),priority:PRIORITY_LEVELS[level],priorityLevel:level,geography,source:{type:fd.get('knowledgeClass')==='expert'?'expert':'reference',title:fd.get('sourceTitle')||'Ikke angivet'},conditions,effect:{scoreAdjustment:Number(fd.get('scoreAdjustment')||0),explanation:fd.get('explanation'),...(fd.get('overrideScore')!==''?{score:Number(fd.get('overrideScore'))}:{}),...(fd.get('block')?{block:true}:{})},notes:fd.get('notes'),version:(old?.version||0)+1,updatedAt:new Date().toISOString()};const rows=adminRules();const i=rows.findIndex(x=>x.id===rule.id);if(i>=0)rows[i]=rule;else rows.push(rule);saveAdminRules(rows);addHistory(i>=0?'updated':'created',rule);ruleDialog.dataset.dirty='false';ruleDialog.close();boot();});

function openTest(rule){const zones=state.zones.slice(0,100);document.querySelector('#testContent').innerHTML=`<div class="form-grid"><label>Zone<select id="testZone">${zones.map(z=>`<option value="${esc(z.properties?.id)}">${esc(z.properties?.name||z.properties?.id)}</option>`).join('')}</select></label><label>Jagtform<select id="testMode"><option value="waders">Waders</option><option value="beach">Strand</option></select></label><label>Grundscore<input id="testBase" type="number" value="50"></label><label>Vindstyrke m/s<input id="testWind" type="number" value="10"></label><label>Vindretning grader<input id="testDir" type="number" value="270"></label><label>Bølgehøjde m<input id="testWave" type="number" step="0.1" value="0.8"></label><label>Vandstand cm<input id="testWater" type="number" value="0"></label><div class="full"><button type="button" id="runTest" class="admin-button">Kør test</button></div><div id="testResult" class="full admin-card"></div></div>`;document.querySelector('#runTest').onclick=()=>{const z=state.zones.find(x=>x.properties?.id===document.querySelector('#testZone').value);const result=evaluateRules({rules:[rule],zone:{id:z?.properties?.id,coastType:z?.properties?.coastType},mode:document.querySelector('#testMode').value,baseScore:Number(document.querySelector('#testBase').value),weather:{windSpeedMps:Number(document.querySelector('#testWind').value),windDirectionDeg:Number(document.querySelector('#testDir').value),waveHeightM:Number(document.querySelector('#testWave').value),waterLevelCm:Number(document.querySelector('#testWater').value)},history:{}});document.querySelector('#testResult').innerHTML=result.matches.length?`<h3>Reglen matcher</h3><p>Resultatscore: <b>${esc(result.score)}</b> · ændring ${result.adjustment>=0?'+':''}${result.adjustment}</p><p>${esc(result.matches[0].explanation)}</p>`:'<h3>Reglen matcher ikke</h3><p>Prøv at ændre testværdierne og se, hvilke forhold der udløser den.</p>'};testDialog.showModal();document.querySelector('#runTest').click();}

function copyRule(r){const copy={...structuredClone(r),id:uid(),name:`Kopi af ${r.name}`,status:'draft',version:1,_origin:undefined};const rows=adminRules();rows.push(copy);saveAdminRules(rows);addHistory('copied',copy);boot();openRuleEditor(copy)}
function exportRules(){download(`ravradar-admin-regler-${new Date().toISOString().slice(0,10)}.json`,{schemaVersion:'1.1',exportedAt:new Date().toISOString(),rules:adminRules()})}
document.querySelector('#importRulesInput').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!Array.isArray(data.rules))throw new Error('Filen indeholder ikke en rules-liste.');const current=adminRules();for(const r of data.rules){const i=current.findIndex(x=>x.id===r.id);if(i>=0)current[i]=r;else current.push(r);addHistory('imported',r)}saveAdminRules(current);await boot();alert(`${data.rules.length} regler importeret.`)}catch(err){alert(`Import mislykkedes: ${err.message}`)}finally{e.target.value=''}});

function describeConditions(c={}){const a=[];if(c.minWindSpeedMps!=null)a.push(`vind ≥ ${c.minWindSpeedMps} m/s`);if(c.maxWindSpeedMps!=null)a.push(`vind ≤ ${c.maxWindSpeedMps} m/s`);if(c.windDirectionRangesDeg?.length)a.push('passende vindretning');if(c.minWaveHeightM!=null)a.push(`bølger ≥ ${c.minWaveHeightM} m`);if(c.maxWaveHeightM!=null)a.push(`bølger ≤ ${c.maxWaveHeightM} m`);if(c.minWaterLevelCm!=null)a.push(`vandstand ≥ ${c.minWaterLevelCm} cm`);if(c.maxWaterLevelCm!=null)a.push(`vandstand ≤ ${c.maxWaterLevelCm} cm`);if(c.maxHoursSinceHighEnergy!=null)a.push(`inden for ${c.maxHoursSinceHighEnergy} timer efter kraftigt vejr`);if(c.huntModes?.length)a.push(`jagtform: ${c.huntModes.join('/')}`);return a.join(', ')}
function describeEffect(r){if(r.kind==='annotation')return'Viser et godt råd';if(r.kind==='gate')return r.effect?.block?'Blokerer vurdering':'Gate';if(r.kind==='override')return`Sætter score til ${r.effect?.score}`;return`${Number(r.effect?.scoreAdjustment||0)>=0?'+':''}${r.effect?.scoreAdjustment||0} point`}
function describeGeo(g={}){if(!g.scope||g.scope==='national')return'Hele Danmark';if(g.scope==='zone')return`${g.zoneIds?.length||0} valgte zoner`;if(g.scope==='coastType')return`Kysttyper: ${(g.coastTypes||[]).join(', ')}`;return g.scope}
function classDa(x){return({expert:'Ravjæger-erfaring',documented:'Dokumenteret','data-derived':'Dataafledt',hypothesis:'Hypotese'})[x]||x}
function statusDa(x){return({active:'Aktiv',draft:'Kladde',inactive:'Inaktiv',retired:'Arkiveret'})[x]||x}
function directionLabelToRange(v){const m={N:[337.5,22.5],NE:[22.5,67.5],E:[67.5,112.5],SE:[112.5,157.5],S:[157.5,202.5],SW:[202.5,247.5],W:[247.5,292.5],NW:[292.5,337.5]};return m[v.toUpperCase()]||String(v).split('-').map(Number)}
function directionRangeToLabel(r){return `${r[0]}-${r[1]}`}


function requestCloseRuleDialog(){if(ruleDialog.dataset.dirty==='true'&&!confirm('Du har ændringer, som ikke er gemt. Vil du lukke alligevel?'))return false;ruleDialog.dataset.dirty='false';ruleDialog.close('cancel');return true;}
ruleDialog.querySelectorAll('[value="cancel"]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();requestCloseRuleDialog()}));
ruleDialog.addEventListener('cancel',event=>{event.preventDefault();requestCloseRuleDialog()});
ruleDialog.addEventListener('click',event=>{if(event.target===ruleDialog)requestCloseRuleDialog()});

const saveBadge=document.createElement('div');
saveBadge.className='admin-save-status';
saveBadge.textContent=centralAdminStorageEnabled()?'Supabase tilsluttet · central lagring klar':'Kun lokal kladde – Supabase-login mangler';
document.body.appendChild(saveBadge);
onAdminSaveStatus(status=>{
  saveBadge.className=`admin-save-status ${status.state}`;
  saveBadge.textContent=status.state==='saving'?'Gemmer…':status.state==='saved'?`Gemt centralt ${status.at?new Date(status.at).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'}):''}`:`Kun lokal kladde${status.error?' · '+status.error:''}`;
});
window.addEventListener('beforeunload',e=>{if(saveBadge.classList.contains('saving')){e.preventDefault();e.returnValue='';}});

boot();
